def moore_bound(d, g):
    if g % 2 == 1:
        k = (g - 1) // 2
        return 1 + d * sum((d - 1)**i for i in range(k))
    else:
        k = g // 2
        return 2 * ( (d - 1)**k - 1 ) // (d - 2)

print(f"Moore bound for d=4, g=7: {moore_bound(4, 7)}")
print(f"Moore bound for d=3, g=7: {moore_bound(3, 7)}")
